import java.io.InputStream;
import java.io.IOException;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private byte readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public boolean hasNext() {
            while (hasNextByte() && buffer[ptr] <= ' ') ptr++;
            return hasNextByte();
        }

        public int nextInt() {
            if (!hasNext()) throw new RuntimeException();
            int n = 0;
            byte b = readByte();
            boolean minus = false;
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            while (b >= '0' && b <= '9') {
                n = n * 10 + (b - '0');
                b = readByte();
            }
            return minus ? -n : n;
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        if (!scanner.hasNext()) return;

        int L = scanner.nextInt();
        int C = scanner.nextInt();

        int[][] A = new int[L][C];
        for (int i = 0; i < L; i++) {
            for (int j = 0; j < C; j++) {
                A[i][j] = scanner.nextInt();
            }
        }

        int N = L - 1;
        int M = C - 1;

        int[] height = new int[M];
        int[] stack = new int[M + 1];
        int[] left = new int[M];
        int[] right = new int[M];

        long maxArea = 0;

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                if ((long) A[i][j] + A[i + 1][j + 1] <= (long) A[i][j + 1] + A[i + 1][j]) {
                    height[j]++;
                } else {
                    height[j] = 0;
                }
            }

            // Monotonic stack to find maximal rectangles for current histogram
            int top = 0;
            for (int j = 0; j < M; j++) {
                while (top > 0 && height[stack[top - 1]] >= height[j]) {
                    top--;
                }
                left[j] = (top == 0) ? 0 : (stack[top - 1] + 1);
                stack[top++] = j;
            }

            top = 0;
            for (int j = M - 1; j >= 0; j--) {
                while (top > 0 && height[stack[top - 1]] >= height[j]) {
                    top--;
                }
                right[j] = (top == 0) ? (M - 1) : (stack[top - 1] - 1);
                stack[top++] = j;
            }

            for (int j = 0; j < M; j++) {
                int h = height[j];
                if (h > 0) {
                    int w = right[j] - left[j] + 1;
                    long area = (long) (h + 1) * (w + 1);
                    if (area > maxArea) {
                        maxArea = area;
                    }
                }
            }
        }

        System.out.println(maxArea);
    }
